import defaultDomEvents from "./event";

type EventElement = {
	addEventListener?: (
		event: string,
		handler: EventListenerOrEventListenerObject,
		options?: boolean
	) => void;
	attachEvent?: (
		event: string,
		handler: EventListenerOrEventListenerObject
	) => void;
	removeEventListener?: (
		event: string,
		handler: EventListenerOrEventListenerObject,
		options?: boolean
	) => void;
	detachEvent?: (
		event: string,
		handler: EventListenerOrEventListenerObject
	) => void;
};

type EventHandler = EventListenerOrEventListenerObject;

type EventBinding = {
	element: EventElement;
	event: string;
	callback: EventHandler;
	capture?: boolean;
};

type AddEvent = (
	el: EventElement,
	event: string,
	handler: EventHandler,
	capture?: boolean
) => void;

type RemoveEvent = AddEvent;

type EventScope = {
	attach: (
		el: EventElement,
		event: string,
		callback: EventHandler,
		capture?: boolean
	) => void;
	detach: (
		el: EventElement,
		event: string,
		callback: EventHandler,
		capture?: boolean
	) => void;
	detachAll: () => void;
	extend: () => EventScope;
};

type EventScopeContext = EventScope & {
	event?: AddEvent;
	eventRemove?: RemoveEvent;
};

type DomEventsFactory = (
	addEvent?: AddEvent,
	removeEvent?: RemoveEvent
) => EventScope;

export default function (): EventScope {
	const domEvents: DomEventsFactory = (
		addEvent = defaultDomEvents.event,
		removeEvent = defaultDomEvents.eventRemove
	) => {
		const handlers: EventBinding[] = [];

		const eventScope: EventScope = {
			attach(
				el: EventElement,
				event: string,
				callback: EventHandler,
				capture?: boolean
			): void {
				handlers.push({
					element: el,
					event,
					callback,
					capture,
				});

				addEvent(el, event, callback, capture);
			},

			detach(
				el: EventElement,
				event: string,
				callback: EventHandler,
				capture?: boolean
			): void {
				removeEvent(el, event, callback, capture);

				for (let i = 0; i < handlers.length; i++) {
					const handler = handlers[i];

					if (
						handler.element === el &&
						handler.event === event &&
						handler.callback === callback &&
						handler.capture === capture
					) {
						handlers.splice(i, 1);
						i--;
					}
				}
			},

			detachAll(): void {
				const staticArray = handlers.slice();

				for (let i = 0; i < staticArray.length; i++) {
					const handler = staticArray[i];

					eventScope.detach(
						handler.element,
						handler.event,
						handler.callback,
						handler.capture
					);
					eventScope.detach(
						handler.element,
						handler.event,
						handler.callback,
						undefined
					);
					eventScope.detach(
						handler.element,
						handler.event,
						handler.callback,
						false
					);
					eventScope.detach(
						handler.element,
						handler.event,
						handler.callback,
						true
					);
				}
				handlers.splice(0, handlers.length);
			},

			extend(this: EventScopeContext): EventScope {
				return domEvents(this.event, this.eventRemove);
			}
		};

		return eventScope;
	};

	return domEvents();
}