type EventId = string | number;
type EventHandler = (...args: any[]) => any;
type HandlerSettings = {
	id?: EventId;
	once?: boolean;
	thisObject?: unknown;
};

interface EventStorage {
	(...args: any[]): boolean;
	addEvent(
		handler: EventHandler,
		settings?: HandlerSettings,
	): EventId | false;
	removeEvent(id: EventId): void;
	clear(): void;
}

class EventHost {
	_silent_mode: boolean;
	listeners: Record<string, EventStorage>;

	constructor() {
		this._silent_mode = false;
		this.listeners = {};
	}
	_silentStart() {
		this._silent_mode = true;
	}
	_silentEnd() {
		this._silent_mode = false;
	}
}

const createEventStorage = function (obj: unknown) {
	let handlers: Record<string, EventHandler> = {};
	let index = 0;
	const eventStorage = function (this: unknown, ...args: any[]) {
		let combinedResult = true;
		for (const i in handlers) {
			const handlerResult = handlers[i].apply(obj, args);
			combinedResult = combinedResult && handlerResult;
		}
		return combinedResult;
	} as EventStorage;
	eventStorage.addEvent = function (
		handler: EventHandler,
		settings?: HandlerSettings,
	) {
		if (typeof handler == "function") {
			let handlerId;
			if (settings && settings.id) {
				handlerId = settings.id;
			} else {
				handlerId = index;
				index++;
			}

			if (settings && settings.once) {
				const originalHandler = handler;
				handler = function () {
					originalHandler();
					eventStorage.removeEvent(handlerId);
				};
			}

			handlers[handlerId] = handler;
			return handlerId;
		}
		return false;
	};
	eventStorage.removeEvent = function (id: EventId) {
		delete handlers[id];
	};

	eventStorage.clear = function () {
		handlers = {};
	};

	return eventStorage;
};

function makeEventable(obj: Record<string, any>) {
	const eventHost = new EventHost();
	obj.attachEvent = function (
		eventName: string,
		handler: EventHandler,
		settings: HandlerSettings,
	) {
		eventName = "ev_" + eventName.toLowerCase();
		if (!eventHost.listeners[eventName]) {
			eventHost.listeners[eventName] = createEventStorage(this);
		}

		if (settings && settings.thisObject) {
			handler = handler.bind(settings.thisObject);
		}

		const innerId = eventHost.listeners[eventName].addEvent(
			handler,
			settings,
		);

		let handlerId: EventId = eventName + ":" + innerId; //return ID (ev_eventname:1)
		if (settings && settings.id) {
			handlerId = settings.id;
		}
		return handlerId;
	};

	obj.attachAll = function (callback: EventHandler) {
		this.attachEvent("listen_all", callback);
	};

	obj.callEvent = function (name: string, eventArguments: any[]) {
		if (eventHost._silent_mode) return true;

		const handlerName = "ev_" + name.toLowerCase();

		const listeners = eventHost.listeners;
		if (listeners["ev_listen_all"]) {
			listeners["ev_listen_all"].apply(
				this,
				[name].concat(eventArguments),
			);
		}

		if (listeners[handlerName])
			return listeners[handlerName].apply(this, eventArguments);
		return true;
	};

	obj.checkEvent = function (name: string) {
		const listeners = eventHost.listeners;
		return !!listeners["ev_" + name.toLowerCase()];
	};

	obj.detachEvent = function (id?: EventId) {
		if (id) {
			let listeners = eventHost.listeners;
			for (const i in listeners) {
				listeners[i].removeEvent(id); //remove event
			}

			const list = String(id).split(":"); //get EventName and ID
			listeners = eventHost.listeners;
			if (list.length === 2) {
				const eventName = list[0];
				const eventId = list[1];
				if (listeners[eventName]) {
					listeners[eventName].removeEvent(eventId); //remove event
				}
			}
		}
	};
	obj.detachAllEvents = function () {
		for (const name in eventHost.listeners) {
			eventHost.listeners[name].clear();
		}
	};
}

export default makeEventable;
